import{_ as i,o as u,c as n,a2 as l}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Nakala 105｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Hatari, Gharama za Kuvunja, na Mfumo wa Usimamizi wa Ālaya","description":"","frontmatter":{"title":"Nakala 105｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Hatari, Gharama za Kuvunja, na Mfumo wa Usimamizi wa Ālaya","no":105,"module":1,"tags":["境界","感元境","修炼风险","突破代价","阿赖耶监管"],"related":["14-修炼境界统一划分","19-修炼伦理与边界","04-反掠夺主义核心论纲","97-设定矛盾自查表"]},"headers":[],"relativePath":"sw/0105_模块1-感元境-风险突破代价与阿赖耶监管.md","filePath":"sw/0105_模块1-感元境-风险突破代价与阿赖耶监管.md"}'),m={name:"sw/0105_模块1-感元境-风险突破代价与阿赖耶监管.md"};function o(t,a,k,s,h,w){return u(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="nakala-105-nguvu-ya-hisi-asili-hatari-gharama-za-kuvunja-na-mfumo-wa-usimamizi-wa-alaya" tabindex="-1">Nakala 105｜Nguvu ya Hisi Asili: Hatari, Gharama za Kuvunja, na Mfumo wa Usimamizi wa Ālaya <a class="header-anchor" href="#nakala-105-nguvu-ya-hisi-asili-hatari-gharama-za-kuvunja-na-mfumo-wa-usimamizi-wa-alaya" aria-label="Permalink to &quot;Nakala 105｜Nguvu ya Hisi Asili: Hatari, Gharama za Kuvunja, na Mfumo wa Usimamizi wa Ālaya&quot;">​</a></h1><ul><li>Moduli: Moduli ya Kwanza · Uboreshaji wa Kina wa Nguvu | Msingi wa Rejeo: Hati 14, 19, 04, 97</li></ul><h2 id="utangulizi-kadri-nguvu-inavyosambaa-ndipo-usimamizi-unavyozidi-lazima" tabindex="-1">Utangulizi: Kadri Nguvu Inavyosambaa, Ndipo Usimamizi Unavyozidi Lazima <a class="header-anchor" href="#utangulizi-kadri-nguvu-inavyosambaa-ndipo-usimamizi-unavyozidi-lazima" aria-label="Permalink to &quot;Utangulizi: Kadri Nguvu Inavyosambaa, Ndipo Usimamizi Unavyozidi Lazima&quot;">​</a></h2><p>Msingi wa ufunguzi kamili wa anga nyingi zaidi wa Heng Yuan Zhou (Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa) hufanya njia za Nguvu ya Hisi Asili zifunguliwe bila malipo kwa Kabila Kumi na Elfu — lakini hii haimaanishi &quot;kuacha tu&quot;. Badala yake: wakati mafunzo yanapoacha kuwa fursa ya wachache na kuwa haki ya msingi ya Kabila Kumi na Elfu, usimamizi unabadilika kutoka &quot;kudhibiti wenye nguvu&quot; hadi &quot;kulinda wote&quot;. Mtandao wa Ālaya + mfumo wa usimamizi wa tabaka nyingi ndiyo miundombinu iliyozaliwa kwa lengo hili.</p><p>Nguvu ya Hisi Asili inaonekana hatari ya chini, lakini ndiyo chanzo cha hatari zote za mafunzo: kila hatari iliyoachwa hapa itaongezwa katika njia ya nguvu tisa. Makala hii inapanga kwa utaratibu hatari, gharama za kuvunja, na mifumo ya usimamizi ya Nguvu ya Hisi Asili.</p><p>Kanuni Muhimu Sita za Juu ni chanzo cha thamani ya mfumo wa usimamizi: Kanuni ya Kupinga Unyanyasaji — dhamana ya kwanza ya usimamizi ni kufanya unyanyasaji kosawe nafasi ya kujificha; Kanuni ya Jamhuri ya Kabila Kumi na Elfu — usimamizi unatibu Kabila Kumi na Elfu kwa usawa; Kanuni ya Kupanda Mwelekeo kwa Pamoja — kulinda mwanafunzi ni kulinda rasilimali ya ustaarabu, kuzuia kipaji kikubwa kutumika kidogo; Kanuni ya Nidhamu ya Sababu-Natija — kila kitendo cha mafunzo hakipaswi kuchanganya sababu ya wengine na mazingira; Kanuni ya Kipaumbele cha Sheria — mfumo wa sheria wa usimamizi wa Ālaya ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, unaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wenye tamaa na Vijana Wakuu wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><h2 id="i-hatari-nne-za-msingi-za-nguvu-ya-hisi-asili" tabindex="-1">I. Hatari Nne za Msingi za Nguvu ya Hisi Asili <a class="header-anchor" href="#i-hatari-nne-za-msingi-za-nguvu-ya-hisi-asili" aria-label="Permalink to &quot;I. Hatari Nne za Msingi za Nguvu ya Hisi Asili&quot;">​</a></h2><ol><li>Kuenda kwa ibilisi: hisi isiyo na mpangilio — wanafunzi wa haraka-wakati wanafungua kwa nguvu njia za hisi, kusababisha nishati kurudi nyuma na fahamu kuchanganyika. Ingawa haina kusababisha kifo katika hatua hii, inaweza kuharibu upeo wa hisi kwa muda wa milele</li><li>Uchafuzi wa nishati: hatua ya kumeza huleta nishati iliyo na uchafu au alama za uamuzi wa mtu mwingine, huchafua ramani ya nishati ya kibinafsi, hupanda mbegu ya &quot;asili isiyo safi&quot; ya baadaye</li><li>Iblisi wa njia ya mkato: aina ya kawaida ya Iblisi wa Njia ya Mkato katika Nguvu ya Hisi Asili ni jaribu la &quot;kumeza nishati ya mtu mwingine ni haraka&quot; — vikosi vilivyobaki vya mfumo wa zamani vinaupenda sana kueneza mafundisho haya ya uongo ya kasi kati ya wanafunzi wa mwanzo</li><li>Hatari ya kunyanganywa: wanafunzi wa mwanzo nishati dhaifu na tahadhari ndogo, wako ndiyo &quot;mawindo&quot; machoni mwa vikosi vilivyobaki vya Kundi la Wawindaji; utumwa wa roho na unyang&#39;anyi wa nishati mara nyingi huanza katika nguvu hii</li></ol><h2 id="ii-gharama-za-kuvunja-zinadhibitiwa-lakini-lazima-ziwe-za-kweli" tabindex="-1">II. Gharama za Kuvunja: Zinadhibitiwa, Lakini Lazima Ziwe za Kweli <a class="header-anchor" href="#ii-gharama-za-kuvunja-zinadhibitiwa-lakini-lazima-ziwe-za-kweli" aria-label="Permalink to &quot;II. Gharama za Kuvunja: Zinadhibitiwa, Lakini Lazima Ziwe za Kweli&quot;">​</a></h2><p>Kuvunja Nguvu ya Hisi Asili na kuingia Nguvu ya Mkusanyiko wa Asili kunahitaji gharama ya kweli:</p><ul><li>Gharama ya wakati: njia ya kawaida wiki hadi miezi (Hati 14); kulazimisha kutoa wakati kunahitaji gharama ya hatari zaidi</li><li>Gharama ya rasilimali: rasilimali ya msingi inatolewa na Mfumo wa Mkataba unaohusishwa na Uzalishaji (Hati 90); kazi nyingi zaidi zawadi zaidi, bila kazi hakuna zawadi — kuzuia &quot;kuchukua rasilimali bure&quot;, na pia kuzuia &quot;ukiritimba wa rasilimali&quot;</li><li>Gharama ya msingi: ikiwa kuvunja kwa nguvu kabla ya utambuzi wa nishati kukamilika, itaacha jeraha la siri la hisi; gharama ya kuvunja ni &quot;kutembea na jeraha&quot; au &quot;kuweka sifuri na kuanza upya&quot;</li><li>Gharama ya kushindwa: kuvunja kwa kushindwa kunaweza kusababisha nishati kurudi nyuma, lakini mfumo wa ufuatiliaji na urekebishaji wa Mtandao wa Nanga unahakikisha kushindwa kunaweza kurejeshwa na kuanza tena</li></ul><p>Kanuni kuu: gharama ya kuvunja lazima iwe ya kweli (kwa sababu vinginevyo ukuaji hauna uzito), lakini kamwe hairuhusiwi uharibifu usioweza kurejeshwa wa aina ya &quot;kosa moja kuwa majuto ya milele&quot; wa Kundi la Wawindaji.</p><h2 id="iii-mtandao-wa-alaya-mfumo-wa-usimamizi-wa-tabaka-nyingi" tabindex="-1">III. Mtandao wa Ālaya + Mfumo wa Usimamizi wa Tabaka Nyingi <a class="header-anchor" href="#iii-mtandao-wa-alaya-mfumo-wa-usimamizi-wa-tabaka-nyingi" aria-label="Permalink to &quot;III. Mtandao wa Ālaya + Mfumo wa Usimamizi wa Tabaka Nyingi&quot;">​</a></h2><p>Usimamizi wa Nguvu ya Hisi Asili huunda mzingo uliofungwa wa &quot;Mtandao wa Ālaya + usimamizi wa tabaka nyingi&quot;:</p><p>Tabaka la kwanza · Ufuatiliaji wa moja kwa wa nanga: Mtandao wa Nanga unafuatilia kwa utaratibu viwango vya nishati, utulivu wa hisi, usafi wa nishati na viashiria vingine (mfumo wa uthibitisho wa Hati 14), isiyo ya kawaida inatoa onyo mara moja Tabaka la pili · Ukaguzi wa maadili: kuvunja kwa juu lazima kupitie Kamati ya Ukaguzi wa Maadili (Hati 17), ikithibitisha msimamo wa kupinga unyanyasaji na wazo la usawa Tabaka la tatu · Kamati ya Kupinga Unyanyasaji: Kamati ya Kupinga Unyanyasaji chini ya Bunge la Jamhuri ya Kabila Kumi na Elfu (Hati 04) inasimamia na kuchunguza matendo ya unyanyasaji, uenezaji wa &quot;mafundisho ya uongo ya kasi&quot; katika Nguvu ya Hisi Asili ni lengo kuu Tabaka la nne · Mahakama ya Nanga na wavu wa usalama wa kimahakama: uhalifu kama utumwa wa roho na unyang&#39;anyi wa nishati hutahamiwa na Mahakama ya Nanga kwa mujibu wa sheria Tabaka la tano · Usimamizi wa ustaarabu: kutangaza na kipindi cha pingamizi (Hati 14) huruhusu kila kiumbe kutoa pingamizi kwa uthibitisho wa kuvunja, haki ya usimamizi ni ya Kabila Kumi na Elfu</p><h2 id="iv-maadili-ya-mafunzo-yanavyotekelezwa-katika-nguvu-ya-hisi-asili" tabindex="-1">IV. Maadili ya Mafunzo Yanavyotekelezwa katika Nguvu ya Hisi Asili <a class="header-anchor" href="#iv-maadili-ya-mafunzo-yanavyotekelezwa-katika-nguvu-ya-hisi-asili" aria-label="Permalink to &quot;IV. Maadili ya Mafunzo Yanavyotekelezwa katika Nguvu ya Hisi Asili&quot;">​</a></h2><p>Kanuni sita za maadili ya mafunzo za Hati 19 zinajitokeza katika Nguvu ya Hisi Asili:</p><ul><li>Heshima ya maisha: mafunzo ya Nguvu ya Hisi Asili kamwe haichukui mwingine kama &quot;nyenzo&quot; au &quot;zana&quot;</li><li>Kupinga unyanyasaji: kigongo cha kwanza cha nishati kinatoka kwa mzunguko, si kwa kumeza</li><li>Ridhaa iliyoarifiwa: mafunzo ya pamoja, ushiriki wa nishati, mafunzo ya pamoja, yote kwa msingi wa hiari</li><li>Madhara kidogo: mafunzo yanafanywa katika maeneo yaliyowekwa, uchafuzi wa nishati hugunduliwa na kusafishwa mara moja</li><li>Uaminifu bila udanganyifu: uthibitisho wa nguvu na taarifa ya mchango haziruhusu udanganyifu</li><li>Wajibu: hata katika Nguvu ya Hisi Asili, lazima kuchukua wajibu wa msingi wa huduma ya jamii — nguvu hata iwe ndogo, kuna wajibu</li></ul><h2 id="v-ulinganisho-msitu-bila-usimamizi-dhidi-ya-ulinzi-wa-mfululizo-wote" tabindex="-1">V. Ulinganisho: Msitu Bila Usimamizi dhidi ya Ulinzi wa Mfululizo Wote <a class="header-anchor" href="#v-ulinganisho-msitu-bila-usimamizi-dhidi-ya-ulinzi-wa-mfululizo-wote" aria-label="Permalink to &quot;V. Ulinganisho: Msitu Bila Usimamizi dhidi ya Ulinzi wa Mfululizo Wote&quot;">​</a></h2><ul><li>Nguvu ya Hisi Asili ya Kundi la Wawindaji: bila usimamizi, kuna msitu tu; bila wajibu, kuna nguvu na udhaifu tu. Bwana anawindwa, mwema anamezwa</li><li>Nguvu ya Hisi Asili ya Kundi la Usawa: ulinzi wa mfululizo wote, hatari zinaweza kuonya, gharama zinaweza kurekebishwa, unyanyasaji unaweza kuhusishwa</li></ul><p>Usimamizi huu sio kizuizi cha uhuru, bali ni utekelezaji wa &quot;Njia kwa Kila Mtu&quot;: tu wakati mwanafunzi dhaifu zaidi wa Nguvu ya Hisi Asili anaweza kufanya mazoezi kwa amani, ndipo ufunguzi wa anga nyingi zaidi ni ufunguzi wa kweli.</p><h2 id="vi-pointi-tano-za-msingi" tabindex="-1">VI. Pointi Tano za Msingi <a class="header-anchor" href="#vi-pointi-tano-za-msingi" aria-label="Permalink to &quot;VI. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: mfumo wa usimamizi unahakikisha kila kipaji hakipotei kwa hatari, kila juhudi haikatiwi na unyanyasaji</li><li>Kupinga unyanyasaji: kupigana na &quot;mafundisho ya uongo ya kasi&quot; kutoka chanzo, kuweka iblisi wa njia ya mkato katika nguvu ya kwanza</li><li>Kulinganisha paa la Táng Luó: katika mfumo wa ustawi wa zama za zamani (Chuo cha Wúshuāng cha Táng Luó) hakukuwa na mtandao wa usimamizi, chini ya zawadi kulikuwa na mito ya siri; ufunguzi wa Heng Yuan Zhou unaambatana na ulinzi wa mfululizo wote</li><li>Kufunika kwa Kabila Kumi na Elfu: mfumo wa usimamizi unatibu Kabila Kumi na Elfu 99% kwa usawa, Maisha ya Kipekee na maisha ya kiwango cha sayari pia zinalindwa na ufuatiliaji wa nanga, kuzuia kipaji chochote kupotea</li><li>Ufunguzi wa kina wa anga nyingi zaidi: kila hatua ya ufunguzi ina ulinzi, ufunguzi na usalama kamwe sio swali moja</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Falsafa ya usimamizi ya Nguvu ya Hisi Asili inaweza kuunganishwa katika sentensi moja: kudhibiti hatari, kuweka gharama za kweli, kufungua njia. Mtandao wa Ālaya + usimamizi wa tabaka nyingi unawapa wanafunzi wa Kabila Kumi na Elfu kwa mara ya kwanza nje ya &quot;usalama kamili&quot; na &quot;usalama bandia&quot;, chaguo la tatu — kukua kwa utulivu katika gharama za kweli na ulinzi wa mfululizo wote. Hii ndiyo sehemu ambayo Ustaarabu wa Usawa wa Nanga ni wa juu kuliko mifumo yote ya unyanyasaji: haitawala kwa hofu, wala kwa ahadi za udanganyifu, bali kwa taasisi zinazowafanya watu kuwa na nguvu kwa amani.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a> · <a href="./19-修炼伦理与边界.html">19-修炼伦理与边界</a> · <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./97-设定矛盾自查表.html">97-设定矛盾自查表</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',27)])])}const z=i(m,[["render",o]]);export{y as __pageData,z as default};
